import React from 'react';
// @ts-ignore
import { WanderConnect } from '@wanderapp/connect';
import { LocalStorage } from 'util/storage';
import { useAppSelector, useAppDispatch } from 'redux/hooks';
import {
  doArInit as doArInitAction,
  doArConnect,
  doArSetAuth as doArSetAuthAction,
  doArUpdateBalance as doArUpdateBalanceAction,
  doCleanTips as doCleanTipsAction,
} from 'redux/actions/arwallet';
import { selectArweaveWanderAuth, selectArweaveAddress, selectArweaveConnecting } from 'redux/selectors/arwallet';
import { selectArAccountRegisteringError } from 'redux/selectors/payments';
import { selectTheme } from 'redux/selectors/settings';
import { selectUserVerifiedEmail } from 'redux/selectors/user';
import './style.scss';
type Props = {};
export default function Wander(props: Props) {
  const dispatch = useAppDispatch();
  const arweaveAddress = useAppSelector(selectArweaveAddress);
  const connecting = useAppSelector(selectArweaveConnecting);
  const theme = useAppSelector(selectTheme);
  const auth = useAppSelector(selectArweaveWanderAuth);
  const authenticated = useAppSelector(selectUserVerifiedEmail);
  const addressInUse = useAppSelector(selectArAccountRegisteringError) === 'address already exists for another user';
  const doArInit = () => dispatch(doArInitAction());
  const connectArWallet = () => dispatch(doArConnect());
  const doArUpdateBalance = () => dispatch(doArUpdateBalanceAction());
  const doCleanTips = () => dispatch(doCleanTipsAction());
  const [instance, setInstance] = React.useState(null);
  const loginTimerRef = React.useRef(null);
  const wrapperRef = React.useRef();
  React.useEffect(() => {
    const arAddressInUse = addressInUse || LocalStorage.getItem('AR_ADDRESS_IN_USE') === 'true';

    if (instance && !arAddressInUse) {
      if (auth?.authStatus === 'onboarding') instance.open();

      if (auth?.authStatus === 'authenticated') {
        // Connected
        if (window.wanderInstance.balanceInfo && !connecting && !arweaveAddress) {
          // Has backup
          connectArWallet();
        } else if (!window.wanderInstance.balanceInfo) {
          // Missing backup
          window.wanderInstance.open();
          connectArWallet();
        }
      }
    } // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [auth]);
  React.useEffect(() => {
    if (authenticated) {
      doArInit();

      if (window.wanderInstance || (WanderConnect as any).instance) return;

      try {
        const wanderInstance = new WanderConnect({
          clientId: 'FREE_TRIAL',
          theme: theme,
          skipStorageAccessWarning: true,
          button: {
            parent: wrapperRef.current,
            label: false,
            customStyles: `
              #wanderConnectButtonHost {
                display:none;
              }`,
          },
          iframe: {
            routeLayout: {
              default: {
                // type: 'dropdown',
                type: 'modal',
              },
              auth: {
                type: 'modal',
              },
              'auth-request': {
                type: 'modal',
              },
            },
            cssVars: {
              light: {
                shadowBlurred: 'none',
              } as any,
              dark: {
                shadowBlurred: 'none',
                boxShadow: 'none',
              } as any,
            },
            customStyles: `
              .backdrop {
                margin-top:var(--header-height);
                background-color: var(--color-background-overlay);
                backdrop-filter: blur(2px);
              }

              .iframe {
                max-width:400px;
              }

              .iframe-wrapper {              
                border-radius: var(--border-radius);
                border: 2px solid var(--color-border) !important;
                background:unset;
                z-index:999999;

                /*
                &[data-layout="dropdown"] {
                  position: fixed;
                  top: var(--header-height) !important;
                  right:1px !important;
                  left:unset !important;
                  min-height: 500px;
                  height: 600px;
                  border-top:unset !important;
                  border-radius: 0 0 var(--border-radius) var(--border-radius);
                  transform: scaleY(0) !important;
                  transform-origin: top;
                  transition: transform .2s !important;

                  &.show{
                    transform: scaleY(1) !important;
                  }

                  & + .backdrop {
                    backdrop-filter: unset;
                    background-color: unset;
                  }
                }
                */
              }
            `,
          },
        });
        setInstance(wanderInstance);
        window.wanderInstance = wanderInstance;
        (window as any).__WANDER_INITIALIZED__ = true;
      } catch (e) {
        if (e?.message && !e.message.includes('already exists')) {
          console.error(e);
        }
      }
    } else {
      try {
        window.wanderInstance.destroy();
      } catch {}
    }

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authenticated]);
  React.useEffect(() => {
    if (window.wanderInstance) {
      const newTheme = theme === 'light' ? 'light' : theme === 'dark' ? 'dark' : 'system';
      window.wanderInstance.setTheme(newTheme);
    }
  }, [theme]);
  React.useEffect(() => {
    if (!instance) return;
    const isWanderApp = navigator.userAgent.includes('WanderMobile');

    if (isWanderApp) {
      window.wanderInstance.authInfo.authType = 'NATIVE_WALLET';
      LocalStorage.setItem('WALLET_TYPE', 'NATIVE_WALLET');
    }

    dispatch(doArSetAuthAction(instance.authInfo));

    const onArweaveWalletLoaded = () => {
      dispatch(doArSetAuthAction(instance.authInfo));
    };

    const onMessage = (event) => {
      try {
        const data = event.data;

        if (data && data.id && !data.id.includes('react')) {
          if (data.type === 'embedded_auth') {
            if (
              data.data.authType ||
              (data.data.authStatus === 'not-authenticated' &&
                data.data.authType !== 'null' &&
                data.data.authType !== null)
            ) {
              if (data.data.authStatus !== 'loading') {
                LocalStorage.setItem('WALLET_TYPE', data.data.authType);

                if (data.data.authStatus === 'authenticated') {
                  LocalStorage.setItem('AR_ADDRESS_IN_USE', 'false');
                }

                window.wanderInstance.close();
                dispatch(doArSetAuthAction(data.data));

                if (data.data.authStatus === 'authenticated') {
                  // Signed in & has backup, clear Interval
                  clearInterval(loginTimerRef.current);
                  loginTimerRef.current = null;
                }
              } else if (!loginTimerRef.current) {
                let s = 0;
                loginTimerRef.current = setInterval(() => {
                  s++;

                  if (s > 50) {
                    if (!window.wanderInstance.openReason) window.wanderInstance.open();
                    s = 0;
                  }
                }, 1000);
              }
            } else if (data.data.authStatus === 'not-authenticated') {
              dispatch(doArSetAuthAction(data.data));
            }
          } else if (data.type === 'embedded_request') {
            if (window.wanderInstance.pendingRequests !== 0) {
              window.wanderInstance.close();
              window.wanderInstance.open();
            } else {
              window.wanderInstance.close();
            }
          } else if (data.type === 'embedded_balance') {
            doArUpdateBalance();
          } else if (data.type === 'embedded_close') {
            doCleanTips();
          } else if (data.type === 'embedded_backup') {
            doArUpdateBalance();
          }
        }
      } catch (e) {
        // Ignore errors from wallet SDK message handling
      }
    };

    window.addEventListener('arweaveWalletLoaded', onArweaveWalletLoaded);
    window.addEventListener('message', onMessage);
    const balanceUpdate = setInterval(() => {
      doArUpdateBalance();
    }, 60000);
    return () => {
      window.removeEventListener('arweaveWalletLoaded', onArweaveWalletLoaded);
      window.removeEventListener('message', onMessage);
      clearInterval(balanceUpdate);
      clearInterval(loginTimerRef.current);
    }; // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [instance, dispatch]);
  return <div className="wanderConnectWrapper" ref={wrapperRef} />;
}
